  x_dev_drift: ['Development moves 2 % of the gap toward its target each month.', 'Die Entwicklung rückt jeden Monat um 2 % des Abstands an ihr Ziel heran.'],
  x_garrison_hint: ['Soldiers of the fortress: 1,000 per fort level once built, 300 per level after the place has changed hands. Fort pay decides how many stand ready in a siege.', 'Soldaten der Festung: 1.000 je Festungsstufe nach dem Bau, 300 je Stufe nach einem Besitzwechsel. Der Festungssold entscheidet, wie viele bei einer Belagerung bereitstehen.'],
  x_devast_hint: ['Plundered land: farms yield up to 70 % less, mines and crafts up to 60 % less, unrest rises. It heals by 1 point a month.', 'Geplündertes Land: Höfe bringen bis zu 70 % weniger, Gruben und Handwerk bis zu 60 % weniger, die Unruhe steigt. Es erholt sich um 1 Punkt im Monat.'],
  x_breaches: ['Breaches', 'Breschen'], x_blockade: ['Blockade from the sea', 'Blockade von See'], x_days: ['Days', 'Tage'],
  x_output_now: ['Output this month', 'Erzeugung in diesem Monat'],
  x_loc_tax_hint: ['Each class pays its income × its rate × control; the crown keeps 8 %, lords, towns and collectors the rest.', 'Jeder Stand zahlt sein Einkommen × Steuersatz × Kontrolle; die Krone behält 8 %, Grundherren, Städte und Eintreiber den Rest.'],
  x_crown_share: ['Crown\'s share', 'Anteil der Krone'], x_occupied_tax: ['Occupied: the occupier collects half of it.', 'Besetzt: der Besatzer treibt die Hälfte davon ein.'],
  x_reach: ['Administrative reach', 'Verwaltungsreichweite'],
  x_control_formula: ['Target: 100 % minus 75 % × distance ÷ reach (at least 12 %), measured from the capital or an administrative seat; roads shorten the way, sea and foreign land lengthen it. Control moves a quarter of the gap each month.', 'Ziel: 100 % minus 75 % × Entfernung ÷ Reichweite (mindestens 12 %), gemessen von der Hauptstadt oder einem Verwaltungssitz; Straßen verkürzen den Weg, Meer und fremdes Land verlängern ihn. Die Kontrolle rückt jeden Monat um ein Viertel des Abstands heran.'],
  x_occupied_control: ['Occupied: the target falls to 40 %.', 'Besetzt: das Ziel sinkt auf 40 %.'],
