export function t(k: string): string { const v = S[k]; return v ? v[lang.value === 'de' ? 1 : 0] : k; }

const REASONS: Record<string, [string, string]> = {
  opinion: ['Opinion of us', 'Meinung über uns'], trust: ['Trust', 'Vertrauen'], war_score: ['War score', 'Kriegspunkte'], demands: ['Our demands', 'Unsere Forderungen'], war_exhaustion: ['Their war exhaustion', 'Ihre Kriegsmüdigkeit'],
  war_length: ['Length of the war', 'Kriegsdauer'], empty_treasury: ['Empty treasury', 'Leere Kasse'], capital_occupied: ['Capital occupied', 'Hauptstadt besetzt'], not_enough_war_score: ['Not enough war score', 'Zu wenig Kriegspunkte'],
  living_standard: ['Living standard', 'Lebensstandard'], taxes: ['Taxes', 'Steuern'], foreign_faith: ['Different faith', 'Anderer Glaube'], foreign_culture: ['Different culture', 'Andere Kultur'], low_control: ['Weak control', 'Schwache Kontrolle'],
  concord: ['Concord', 'Eintracht'], devastation: ['Devastation', 'Verwüstung'], inflation: ['Inflation', 'Inflation'], not_integrated: ['Not integrated', 'Nicht integriert'],
};
export function reason(k: string): string {
  const v = REASONS[k]; if (v) return v[lang.value === 'de' ? 1 : 0];
  return k.replace(/_/g, ' ').replace(/^./, (c) => c.toUpperCase());
}

